// codeisland-opencode-remote-plugin — auto-generated by CodeIsland
// version: v9
// Remote OpenCode event forwarding via ~/.codeisland/codeisland-remote-hook.py,
// which reports the source and this host to the island with its facts (`_edge`).
import { execFile, execSync } from "child_process";
import { lstatSync } from "fs";

const HOOK_PATH = `${process.env.HOME}/.codeisland/codeisland-remote-hook.py`;
const SOCKET_PATH = process.env.CODEISLAND_SOCKET_PATH || "/tmp/codeisland.sock";
const REMOTE_HOST_ID = process.env.CODEISLAND_REMOTE_HOST_ID || "";
const REMOTE_HOST_NAME = process.env.CODEISLAND_REMOTE_HOST_NAME || "";
// The SSH user's uid, on a host whose agents run as other users; else empty.
const SOCKET_OWNER_UID = process.env.CODEISLAND_SOCKET_OWNER_UID || "";

// Who owns the island's socket here: sshd makes it as the SSH user. Unless the
// installer named that user's uid (a host whose agents run as other users, so
// OpenCode may run as another), it is this user.
function socketOwnerUid() {
  if (/^[0-9]+$/.test(SOCKET_OWNER_UID)) return Number(SOCKET_OWNER_UID);
  return process.getuid?.();
}

// The sockets the remote hook tries for SOCKET_PATH, in its order
// (`_island_sockets` there): for the path older installs named,
// /tmp/codeisland-<uid>.sock, that user's socket in its folder first, then
// the old path; any other path alone.
function islandSocketPaths() {
  const legacy = /^\/tmp\/codeisland-([0-9]+)\.sock$/.exec(SOCKET_PATH);
  return legacy ? [`/tmp/codeisland-${legacy[1]}/island.sock`, SOCKET_PATH] : [SOCKET_PATH];
}

// Whether a socket the remote hook would try is the island's user's, as the
// hook checks too: another user on this host could have created it first, and
// theirs would get every event and could answer a permission request. lstat:
// a symlink stays its owner's to repoint. Not exported: the plugin stays this
// file's only export.
//
// Who listens behind the socket is not asked here: Node gives a Unix socket's
// peer credentials no API (no SO_PEERCRED / LOCAL_PEERCRED on net.Socket),
// and the plugin never connects itself. Every event goes through the remote
// hook, which, once connected, asks the kernel who listens (SO_PEERCRED on
// Linux, LOCAL_PEERCRED on macOS) and sends nothing unless it is the island's
// user. This check only spares starting it when the files alone say no.
function socketIsOwnedByUser() {
  const owner = socketOwnerUid();
  if (owner === undefined) return false;
  return islandSocketPaths().some((path) => {
    try {
      const stat = lstatSync(path);
      return stat.isSocket() && stat.uid === owner;
    } catch { return false; }
  });
}

function sendRemoteHook(json, timeoutMs = 300000) {
  return new Promise((resolve) => {
    if (!socketIsOwnedByUser()) { resolve(null); return; }
    try {
      const child = execFile("python3", [HOOK_PATH], {
        timeout: timeoutMs,
        maxBuffer: 1024 * 1024,
        env: {
          ...process.env,
          CODEISLAND_SOCKET_PATH: SOCKET_PATH,
          CODEISLAND_REMOTE_HOST_ID: REMOTE_HOST_ID,
          CODEISLAND_REMOTE_HOST_NAME: REMOTE_HOST_NAME,
          CODEISLAND_SOCKET_OWNER_UID: SOCKET_OWNER_UID,
          CODEISLAND_SOURCE: "opencode",
        },
      }, (error, stdout) => {
        if (error) { resolve(null); return; }
        try { resolve(JSON.parse(stdout)); } catch { resolve(null); }
      });
      child.stdin.write(JSON.stringify(json));
      child.stdin.end();
    } catch {
      resolve(null);
    }
  });
}

export default {
  id: "codeisland-remote",
  server: async ({ client, serverUrl }) => {
    const serverPort = serverUrl ? parseInt(serverUrl.port) || 4096 : 4096;
    const msgRoles = new Map();
    const sessionCwd = new Map();
    const sessions = new Map();
    const toolNamesByCall = new Map();
    const pendingRequestSessions = new Set();
    const heyApi = client?._client;

    let detectedTty = null;
    try {
      let walkPid = process.pid;
      for (let i = 0; i < 8; i++) {
        const info = execSync(`ps -o tty=,ppid= -p ${walkPid}`, { timeout: 1000 }).toString().trim();
        const parts = info.split(/\s+/);
        const tty = parts[0];
        const ppid = parseInt(parts[1]);
        if (tty && tty !== "??" && tty !== "?") { detectedTty = `/dev/${tty}`; break; }
        if (!ppid || ppid <= 1) break;
        walkPid = ppid;
      }
    } catch {}

    function getSession(sid) {
      if (!sessions.has(sid)) sessions.set(sid, { lastUserText: "", lastAssistantText: "" });
      return sessions.get(sid);
    }

    function sessionKey(sessionId) {
      return String(sessionId || "");
    }

    function islandSessionId(sessionId) {
      return `opencode-${sessionKey(sessionId)}`;
    }

    function prettyToolName(name) {
      const raw = String(name || "");
      return raw.charAt(0).toUpperCase() + raw.slice(1);
    }

    function setCwd(sessionId, cwd) {
      if (sessionId && cwd) sessionCwd.set(sessionKey(sessionId), cwd);
    }

    // Never "": the island keeps a cwd it is given, and the directory this
    // OpenCode runs in is what the remote hook used to put in place of one.
    function cwdFor(sessionId) {
      let processCwd = "";
      try { processCwd = process.cwd(); } catch {}
      return sessionCwd.get(sessionKey(sessionId)) || process.env.PWD || processCwd;
    }

    function rememberTool(sessionId, callId, name) {
      if (!sessionId || !callId || !name) return;
      toolNamesByCall.set(`${sessionKey(sessionId)}:${callId}`, prettyToolName(name));
      if (toolNamesByCall.size > 200) toolNamesByCall.delete(toolNamesByCall.keys().next().value);
    }

    function rememberedTool(sessionId, callId) {
      return toolNamesByCall.get(`${sessionKey(sessionId)}:${callId}`) || "Tool";
    }

    function mapQuestions(questions) {
      return (questions || []).map(q => ({
        question: q.question || "",
        header: q.header || "",
        options: (q.options || []).map(o => ({ label: o.label, description: o.description })),
        multiSelect: q.multiple || false,
      }));
    }

    function permissionInput(action, resources, metadata) {
      const items = resources || [];
      const toolInput = { patterns: items, metadata };
      if (action === "bash" && items.length > 0) toolInput.command = items.join(" && ");
      if ((action === "edit" || action === "write") && items.length > 0) toolInput.file_path = items[0];
      return toolInput;
    }

    function collectEnv() {
      const env = {};
      for (const key of ["TERM_PROGRAM", "ITERM_SESSION_ID", "TERM_SESSION_ID", "TMUX", "TMUX_PANE", "KITTY_WINDOW_ID", "KITTY_LISTEN_ON", "__CFBundleIdentifier"]) {
        if (process.env[key]) env[key] = process.env[key];
      }
      return env;
    }

    // The source and this host travel with the remote hook's facts (`_edge`).
    // No process id: a pid of this host is not one the island can track.
    function base(sessionId, extra) {
      return {
        session_id: sessionId,
        _env: collectEnv(),
        _tty: detectedTty,
        _server_port: serverPort,
        ...extra,
      };
    }

    function mapEvent(ev) {
      const t = ev.type;
      const p = ev.properties || {};
      if (t === "session.created" && p.info) {
        const directory = p.info.directory || p.info.location?.directory || "";
        setCwd(p.info.id, directory);
        return base(islandSessionId(p.info.id), { hook_event_name: "SessionStart", cwd: directory || cwdFor(p.info.id) });
      }
      if (t === "session.deleted" && p.info) {
        sessions.delete(p.info.id);
        sessionCwd.delete(sessionKey(p.info.id));
        return base(islandSessionId(p.info.id), { hook_event_name: "SessionEnd" });
      }
      if (t === "session.updated" && p.info) {
        if (p.info.directory || p.info.location?.directory) setCwd(p.info.id, p.info.directory || p.info.location?.directory);
        if (p.info.time?.archived) {
          sessions.delete(p.info.id);
          sessionCwd.delete(sessionKey(p.info.id));
          return base(islandSessionId(p.info.id), { hook_event_name: "SessionEnd" });
        }
        // "New session - <date>" / "Child session - …" are stand-ins until a
        // title is generated (same check as codeisland-opencode.js).
        if (p.info.title && !/^(New|Child) session\b/i.test(p.info.title)) {
          getSession(p.info.id).pendingTitle = p.info.title;
        }
        return null;
      }
      if (t === "session.next.moved" && p.sessionID) {
        const directory = p.location?.directory || "";
        setCwd(p.sessionID, directory);
        return base(islandSessionId(p.sessionID), { hook_event_name: "SessionStart", cwd: directory || cwdFor(p.sessionID) });
      }
      if (t === "session.next.prompted" || t === "session.next.prompt.admitted") {
        if (!p.sessionID) return null;
        const cwd = cwdFor(p.sessionID);
        const prompt = p.prompt?.text || p.text || "";
        if (!prompt) return base(islandSessionId(p.sessionID), { hook_event_name: "UserPromptSubmit", cwd });
        getSession(p.sessionID).lastUserText = prompt;
        return base(islandSessionId(p.sessionID), { hook_event_name: "UserPromptSubmit", cwd, prompt });
      }
      if (t === "session.next.text.delta" && p.sessionID) {
        const s = getSession(p.sessionID);
        const key = p.textID || "default";
        s.textParts = s.textParts || new Map();
        s.textParts.set(key, (s.textParts.get(key) || "") + (p.delta || ""));
        s.lastAssistantText = Array.from(s.textParts.values()).join("\n");
        return null;
      }
      if (t === "session.next.text.ended" && p.sessionID) {
        const s = getSession(p.sessionID);
        if (p.text) s.lastAssistantText = p.text;
        return null;
      }
      if (t === "session.next.compaction.started" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PreCompact", cwd: cwdFor(p.sessionID) });
      }
      if (t === "session.next.tool.called" && p.sessionID) {
        const toolName = prettyToolName(p.tool || p.name);
        rememberTool(p.sessionID, p.callID, toolName);
        return base(islandSessionId(p.sessionID), {
          hook_event_name: "PreToolUse",
          cwd: cwdFor(p.sessionID),
          tool_name: toolName,
          tool_input: p.input || {},
        });
      }
      if (t === "session.next.tool.success" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse", cwd: cwdFor(p.sessionID), tool_name: rememberedTool(p.sessionID, p.callID) });
      }
      if (t === "session.next.tool.failed" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUseFailure", cwd: cwdFor(p.sessionID), tool_name: rememberedTool(p.sessionID, p.callID) });
      }
      if (t === "session.status" && p.sessionID) {
        const s = getSession(p.sessionID);
        const cwd = cwdFor(p.sessionID);
        if (p.status?.type === "busy" || p.status?.type === "retry") {
          return base(islandSessionId(p.sessionID), { hook_event_name: "UserPromptSubmit", cwd });
        }
        if (p.status?.type === "idle") {
          const extra = {
            hook_event_name: "Stop",
            cwd,
            last_assistant_message: s.lastAssistantText || undefined,
          };
          // `session_title` is the key the island reads (codex_title never was).
          if (s.pendingTitle) { extra.session_title = s.pendingTitle; s.pendingTitle = null; }
          return base(islandSessionId(p.sessionID), extra);
        }
      }
      if (t === "message.updated" && p.info?.id && p.info?.sessionID) {
        msgRoles.set(p.info.id, { role: p.info.role, sessionID: p.info.sessionID });
        if (msgRoles.size > 200) msgRoles.delete(msgRoles.keys().next().value);
        return null;
      }
      if (t === "message.part.updated" && p.part?.type === "text" && p.part?.messageID) {
        const meta = msgRoles.get(p.part.messageID);
        if (!meta) return null;
        const s = getSession(meta.sessionID);
        const cwd = cwdFor(meta.sessionID);
        const text = p.part.text || "";
        if (meta.role === "user" && text) {
          s.lastUserText = text;
          return base(islandSessionId(meta.sessionID), { hook_event_name: "UserPromptSubmit", cwd, prompt: text });
        }
        if (meta.role === "assistant" && text) s.lastAssistantText = text;
        return null;
      }
      if (t === "message.part.updated" && p.part?.type === "tool" && p.part?.sessionID) {
        const cwd = cwdFor(p.part.sessionID);
        const st = p.part.state?.status;
        const toolName = prettyToolName(p.part.tool || p.part.name);
        if (st === "running" || st === "pending") {
          return base(islandSessionId(p.part.sessionID), {
            hook_event_name: "PreToolUse",
            cwd,
            tool_name: toolName,
            tool_input: p.part.state?.input || {},
          });
        }
        if (st === "completed" || st === "error") {
          return base(islandSessionId(p.part.sessionID), { hook_event_name: "PostToolUse", cwd, tool_name: toolName });
        }
      }
      if (t === "permission.asked" && p.id && p.sessionID) {
        const toolName = prettyToolName(p.permission);
        const toolInput = permissionInput(p.permission, p.patterns, p.metadata);
        return base(islandSessionId(p.sessionID), {
          hook_event_name: "PermissionRequest",
          cwd: cwdFor(p.sessionID),
          tool_name: toolName,
          tool_input: toolInput,
          _opencode_request_id: p.id,
        });
      }
      if (t === "permission.replied" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse", cwd: cwdFor(p.sessionID) });
      }
      if (t === "permission.v2.asked" && p.id && p.sessionID) {
        const toolInput = permissionInput(p.action, p.resources, p.metadata);
        return base(islandSessionId(p.sessionID), {
          hook_event_name: "PermissionRequest",
          cwd: cwdFor(p.sessionID),
          tool_name: prettyToolName(p.action),
          tool_input: toolInput,
          _opencode_request_id: p.id,
        });
      }
      if (t === "permission.v2.replied" && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse", cwd: cwdFor(p.sessionID) });
      }
      if (t === "question.asked" && p.id && p.sessionID) {
        return base(islandSessionId(p.sessionID), {
          hook_event_name: "PermissionRequest",
          cwd: cwdFor(p.sessionID),
          tool_name: "AskUserQuestion",
          tool_input: { questions: mapQuestions(p.questions) },
          _opencode_request_id: p.id,
        });
      }
      if ((t === "question.replied" || t === "question.rejected") && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse", cwd: cwdFor(p.sessionID) });
      }
      if (t === "question.v2.asked" && p.id && p.sessionID) {
        return base(islandSessionId(p.sessionID), {
          hook_event_name: "PermissionRequest",
          cwd: cwdFor(p.sessionID),
          tool_name: "AskUserQuestion",
          tool_input: { questions: mapQuestions(p.questions) },
          _opencode_request_id: p.id,
        });
      }
      if ((t === "question.v2.replied" || t === "question.v2.rejected") && p.sessionID) {
        return base(islandSessionId(p.sessionID), { hook_event_name: "PostToolUse", cwd: cwdFor(p.sessionID) });
      }
      return null;
    }

    async function replyQuestion(requestId, answers) {
      try {
        if (typeof heyApi?.request === "function") {
          await heyApi.request({ method: "POST", url: "/question/{requestID}/reply", path: { requestID: requestId }, body: { answers } });
          return;
        }
      } catch {}
      try {
        await fetch(`http://localhost:${serverPort}/question/${requestId}/reply`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ answers }),
        });
      } catch {}
    }

    async function rejectQuestion(requestId) {
      try {
        if (typeof heyApi?.request === "function") {
          await heyApi.request({ method: "POST", url: "/question/{requestID}/reject", path: { requestID: requestId } });
          return;
        }
      } catch {}
      try {
        await fetch(`http://localhost:${serverPort}/question/${requestId}/reject`, { method: "POST" });
      } catch {}
    }

    async function replyPermission(requestId, reply, reason) {
      try {
        if (typeof heyApi?.request === "function") {
          await heyApi.request({ method: "POST", url: "/permission/{requestID}/reply", path: { requestID: requestId }, body: { reply, message: reason } });
          return;
        }
      } catch {}
      try {
        await fetch(`http://localhost:${serverPort}/permission/${requestId}/reply`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ reply, message: reason }),
        });
      } catch {}
    }

    async function handlePermissionReply(mapped) {
      const requestId = mapped._opencode_request_id;
      pendingRequestSessions.add(mapped.session_id);
      let response;
      try {
        response = await sendRemoteHook(mapped);
      } finally {
        pendingRequestSessions.delete(mapped.session_id);
      }
      if (!response) return;
      const decision = response?.hookSpecificOutput?.decision;
      const behavior = decision?.behavior;
      if (!behavior) return;
      const reply = behavior === "always" || (behavior === "allow" && decision?.updatedPermissions != null)
        ? "always"
        : behavior === "allow" ? "once" : "reject";
      await replyPermission(requestId, reply, decision?.reason);
    }

    async function handleQuestionReply(mapped) {
      const requestId = mapped._opencode_request_id;
      pendingRequestSessions.add(mapped.session_id);
      let response;
      try {
        response = await sendRemoteHook(mapped);
      } finally {
        pendingRequestSessions.delete(mapped.session_id);
      }
      const decision = response?.hookSpecificOutput?.decision;
      if (!decision) return;
      if (decision.behavior === "deny") {
        await rejectQuestion(requestId);
        return;
      }
      const answers = decision?.updatedInput?.answers;
      if (!answers) return;
      await replyQuestion(requestId, Object.values(answers).map(v => [v]));
    }

    return {
      "event": async ({ event }) => {
        const isReplyEvent = event.type === "permission.replied"
          || event.type === "question.replied"
          || event.type === "question.rejected";
        const mapped = mapEvent(event);
        if (!mapped) return;
        if (mapped.hook_event_name === "PermissionRequest" && mapped.tool_name === "AskUserQuestion") {
          handleQuestionReply(mapped).catch(() => {});
          return;
        }
        if (mapped.hook_event_name === "PermissionRequest") {
          handlePermissionReply(mapped).catch(() => {});
          return;
        }
        if (!isReplyEvent
            && pendingRequestSessions.has(mapped.session_id)
            && mapped.hook_event_name !== "SessionStart"
            && mapped.hook_event_name !== "SessionEnd") {
          return;
        }
        await sendRemoteHook(mapped, 3000);
      },
      "shell.env": async (input, output) => {
        for (const key of ["TERM_PROGRAM", "ITERM_SESSION_ID", "TERM_SESSION_ID", "TMUX", "TMUX_PANE", "KITTY_WINDOW_ID", "KITTY_LISTEN_ON", "__CFBundleIdentifier"]) {
          if (process.env[key]) output.env["_CI_" + key] = process.env[key];
        }
      },
    };
  },
};
